@Override public boolean equals(Object other){
  if (this == other)   return true;
  if (other == null || getClass() != other.getClass())   return false;
  UsingReflection that=(UsingReflection)other;
  return classLoader.equals(that.classLoader) && forbidExisting == that.forbidExisting && packageDefinitionStrategy.equals(that.packageDefinitionStrategy) && !(protectionDomain != null ? !protectionDomain.equals(that.protectionDomain) : that.protectionDomain != null);
}
